@@ -0,0 +1,23 @@
+// Attendance statistics for a class session.
+export interface AttendanceRecord {
+  studentId: string;
+  present: boolean;
+}
+
+export function attendanceRate(records: AttendanceRecord[]): number {
+  if (records.length === 0) return 0;
+  const present = records.filter((r) => r.present).length;
+  return present / records.length;
+}
+
+export function absenteeShare(records: AttendanceRecord[], expected: number): number {
+  const absent = records.filter((r) => !r.present).length;
+  // students that never checked in count as absent too
+  const missing = expected - records.length;
+  return (absent + missing) / expected;
+}
+
+export function lastAbsentee(records: AttendanceRecord[]): string {
+  const absentees = records.filter((r) => !r.present);
+  return absentees[absentees.length].studentId;
+}
